Widget build() {
return SessionReplayPrivacy(
textAndInputPrivacyLevel: TextAndInputPrivacyLevel.maskAllInputs,
child: TextField(
decoration: InputDecoration(
labelText: 'Simple Text Field',
),
),
);
}
}
